from datetime import datetime
# Ensure we have gmail access token
if 'res' in globals() and isinstance(res, dict) and 'access_token' in res:
    gmail_access_token = res['access_token']
else:
    raise RuntimeError('Missing gmail access token variable res')

print('gmail_access_token_present', bool(gmail_access_token))

# Search for candidate threads containing checklist / get-together keywords
query = 'checklist get-together get together friends coworkers'
threads = []
page_index = 0
page_limit = 10
while True:
    out = apis.gmail.show_inbox_threads(access_token=gmail_access_token, query=query, page_index=page_index, page_limit=page_limit, sort_by='-updated_at')
    print('page', page_index, 'count', len(out.get('email_threads', [])) if isinstance(out, dict) else out)
    # The API might return different key names; inspect keys
    if isinstance(out, dict):
        # try common keys
        if 'email_threads' in out:
            page_items = out['email_threads']
        elif 'threads' in out:
            page_items = out['threads']
        elif 'results' in out:
            page_items = out['results']
        else:
            page_items = []
    else:
        page_items = []
    if not page_items:
        break
    threads.extend(page_items)
    page_index += 1
    if page_index > 20:
        break

print('total_threads_found', len(threads))
# Print basic info
for t in threads[:20]:
    print(t.get('email_thread_id'), t.get('subject'), t.get('from_email') or t.get('participants'), t.get('preview'))

