# Continue shopping: find Amazon product IDs matching each checklist item
import re

desired_items = [
    (3, 'Rubbermaid Brute 32-Gallon Trash Can'),
    (3, 'CVS Health Family First Aid Kit, 300 Pieces'),
    (2, 'GustBuster Classic Wind-Resistant Umbrella'),
    (1, 'Hefty Strong Multipurpose Large Blackout Trash Bags'),
    (2, 'Sawyer Products Premium Permethrin Insect Repellent'),
    (2, 'EltaMD UV Clear Broad-Spectrum SPF 46'),
]

# Reuse existing amazon_token from earlier (login done)
if 'amazon_token' not in globals() or not amazon_token:
    raise RuntimeError('missing amazon_token')

# helper: loop through all pages of search_products for a given query

def search_all_pages(query, page_limit=5):
    page_index = 0
    all_results = []
    while True:
        out = apis.amazon.search_products(query=query, page_index=page_index, page_limit=page_limit, sort_by='-rating')
        if not out:
            break
        all_results.extend(out)
        page_index += 1
        if page_index > 200:
            break
    return all_results


def score_match(item_desc, product):
    # product has name, description, maybe color
    hay = (str(product.get('name','')) + ' ' + str(product.get('description',''))).lower()
    score = 0
    # extract numbers
    nums = set(re.findall(r'\d+', item_desc))
    # mapping by specific item type based on key brand
    desc_lower = item_desc.lower()

    def has(s):
        return s.lower() in hay

    if 'rubbermaid' in desc_lower:
        required = ['rubbermaid', 'brute', 'trash', 'can']
        extra = ['32', '32-gallon', '32 gallon']
        for k in required:
            if has(k): score += 2
        for k in extra:
            if has(k): score += 3
    elif 'cvs' in desc_lower:
        required = ['cvs', 'family', 'first aid', 'kit']
        for k in required:
            if k in hay: score += 2
        for n in nums:
            if n in hay: score += 3
    elif 'gustbuster' in desc_lower:
        required = ['gustbuster', 'umbrella']
        for k in required:
            if has(k): score += 2
        for k in ['wind', 'resistant', 'classic']:
            if has(k): score += 1
    elif 'hefty' in desc_lower:
        required = ['hefty', 'trash', 'bags', 'large']
        for k in required:
            if k in hay: score += 2
        for k in ['strong', 'multipurpose', 'blackout']:
            if k in hay: score += 2
    elif 'sawyer' in desc_lower:
        required = ['sawyer', 'permethrin', 'insect', 'repellent']
        for k in required:
            if k in hay: score += 2
    elif 'eltamd' in desc_lower:
        required = ['eltamd', 'uv clear', 'spf']
        for k in required:
            if k in hay: score += 2
        for n in nums:
            if n in hay: score += 3

    # small bonus if brand first word appears
    brand_word = item_desc.split()[0].lower()
    if brand_word in hay:
        score += 1
    return score


# For each desired item, find best product with enough inventory
selected = []
for qty, desc in desired_items:
    print('\nSearching:', desc)
    results = search_all_pages(desc, page_limit=5)
    print('results_count', len(results))
    # compute score and filter inventory
    scored = []
    for r in results:
        inv = r.get('inventory_quantity', 0)
        s = score_match(desc, r)
        scored.append((s, inv, r))
    # choose best with inv>=qty
    eligible = [t for t in scored if t[0] > 0 and t[1] >= qty]
    if eligible:
        best = max(eligible, key=lambda x: (x[0], x[1]))
    else:
        best = max(scored, key=lambda x: (x[0], x[1]))
    best_score, best_inv, best_r = best
    print('best_score', best_score, 'best_inv', best_inv)
    print('best_product_id', best_r['product_id'], 'name', best_r['name'], 'rating', best_r.get('rating'), 'price', best_r.get('price'))
    selected.append((qty, desc, best_r['product_id']))

print('\nSelected products:', selected)

