import re

# Use already-parsed items if available
if 'items' not in globals():
    fs_pw = [x['password'] for x in apis.supervisor.show_account_passwords() if x['account_name']=='file_system'][0]
    fs_token = apis.file_system.login(username='va-blac@gmail.com', password=fs_pw)['access_token']
    checklist_path = '/home/valerie/downloads/get-together-shopping-list.txt'
    content = apis.file_system.show_file(file_path=checklist_path, access_token=fs_token)['content']
    items=[]
    for line in content.splitlines():
        line=line.strip()
        if not line.startswith('- '):
            continue
        m=re.match(r'-\s*(\d+)\s*X\s*(.+)$', line)
        if m:
            qty=int(m.group(1))
            desc=m.group(2).strip()
            items.append((qty, desc))

print('checklist_items', items)

# Ensure amazon_token exists
if 'amazon_token' not in globals() or not amazon_token:
    amazon_pw = [x['password'] for x in apis.supervisor.show_account_passwords() if x['account_name']=='amazon'][0]
    amazon_token = apis.amazon.login(username='va-blac@gmail.com', password=amazon_pw)['access_token']

# Score function

def score_match(item_desc, product):
    hay = (str(product.get('name','')) + ' ' + str(product.get('description',''))).lower()
    score = 0
    desc_lower = item_desc.lower()

    def has(s):
        return s.lower() in hay

    if 'rubbermaid' in desc_lower:
        required = ['rubbermaid', 'brute', 'trash', 'can']
        for k in required:
            if has(k): score += 3
        # size hints
        for k in ['32', '32-gallon', '32 gallon', '32-gallon trash']:
            if has(k): score += 2
    elif 'cvs' in desc_lower:
        for k in ['cvs','family','first aid','kit']:
            if has(k): score += 2
        # piece count numeric hint
        nums = re.findall(r'\d+', item_desc)
        for n in nums:
            if n and n in hay:
                score += 1
    elif 'gustbuster' in desc_lower:
        for k in ['gustbuster','umbrella','wind','resistant']:
            if has(k): score += 2
    elif 'hefty' in desc_lower:
        for k in ['hefty','trash','bags']:
            if has(k): score += 2
        for k in ['large','blackout','multipurpose','strong']:
            if has(k): score += 1
    elif 'sawyer' in desc_lower:
        for k in ['sawyer','permethrin','insect','repellent']:
            if has(k): score += 2
    elif 'eltamd' in desc_lower:
        for k in ['eltamd','uv','clear']:
            if has(k): score += 2
        for k in ['spf']:
            if has(k): score += 2
        nums = re.findall(r'\d+', item_desc)
        for n in nums:
            if n in hay:
                score += 2
    else:
        # generic keyword overlap
        for token in desc_lower.split():
            token = token.strip(',-.').lower()
            if token and token in hay:
                score += 0.5

    # brand word bonus
    brand_word = item_desc.split()[0].lower()
    if brand_word in hay:
        score += 1

    return score


def pick_product_for_item(qty, desc, max_pages=2, page_limit=20):
    best=None
    best_score=-1
    # try first few pages
    for page_index in range(max_pages):
        results = apis.amazon.search_products(query=desc, page_index=page_index, page_limit=page_limit, sort_by='-rating')
        print('search page', page_index, 'returned', len(results) if results else 0, 'for', desc[:40])
        if not results:
            break
        for r in results:
            inv = r.get('inventory_quantity', 0)
            s = score_match(desc, r)
            if inv >= qty:
                if s > best_score or (s == best_score and r.get('price',0) < best.get('price', float('inf'))):
                    best = r
                    best_score = s
    # if no eligible inventory, pick best scoring regardless inv
    if best is None:
        for page_index in range(max_pages):
            results = apis.amazon.search_products(query=desc, page_index=page_index, page_limit=page_limit, sort_by='-rating')
            if not results:
                break
            for r in results:
                s = score_match(desc, r)
                if s > best_score:
                    best=r
                    best_score=s

    return best, best_score

selected=[]
for qty, desc in items:
    best, best_score = pick_product_for_item(qty, desc, max_pages=2, page_limit=20)
    if not best:
        raise RuntimeError(f'No product found for {desc}')
    print('selected for', desc, 'qty', qty, '-> product_id', best['product_id'], 'name', best['name'], 'price', best.get('price'), 'inv', best.get('inventory_quantity'), 'score', best_score)
    selected.append({'qty': qty, 'desc': desc, 'product': best})

print('selected_summary', [(s['qty'], s['product']['product_id'], s['product']['name']) for s in selected])

